-- +goose Up
CREATE TABLE agents (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', enabled BOOLEAN NOT NULL DEFAULT TRUE, archived BOOLEAN NOT NULL DEFAULT FALSE, current_version_id TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE agent_versions (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, version INTEGER NOT NULL, schema_version INTEGER NOT NULL, config_json TEXT NOT NULL, config_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL, UNIQUE(agent_id,version));
CREATE TABLE mcp_servers (id TEXT PRIMARY KEY, name TEXT NOT NULL, endpoint TEXT NOT NULL, transport TEXT NOT NULL, auth_env TEXT NOT NULL DEFAULT '', enabled BOOLEAN NOT NULL, validation_state TEXT NOT NULL, latest_discovery_id TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE mcp_discoveries (id TEXT PRIMARY KEY, server_id TEXT NOT NULL, discovery_hash TEXT NOT NULL, created_at TIMESTAMPTZ NOT NULL);
CREATE TABLE mcp_tools (discovery_id TEXT NOT NULL REFERENCES mcp_discoveries(id) ON DELETE RESTRICT, remote_name TEXT NOT NULL, schema_json TEXT NOT NULL, schema_hash TEXT NOT NULL, PRIMARY KEY(discovery_id,remote_name));
CREATE TABLE agent_mcp_tools (agent_version_id TEXT NOT NULL REFERENCES agent_versions(id) ON DELETE RESTRICT, mcp_server_id TEXT NOT NULL, remote_name TEXT NOT NULL, schema_hash TEXT NOT NULL, required BOOLEAN NOT NULL, PRIMARY KEY(agent_version_id,mcp_server_id,remote_name));
CREATE TABLE sessions (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, agent_version_id TEXT NOT NULL REFERENCES agent_versions(id) ON DELETE RESTRICT, config_hash TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, status TEXT NOT NULL, provider_stack_json TEXT NOT NULL, turn_count INTEGER NOT NULL, safe_summary TEXT NOT NULL);
CREATE TABLE turns (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE RESTRICT, ordinal INTEGER NOT NULL, started_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, transcript TEXT, assistant_text TEXT, latencies_json TEXT NOT NULL, interrupted BOOLEAN NOT NULL, tools_json TEXT NOT NULL, UNIQUE(session_id,ordinal));
CREATE TABLE trace_spans (id TEXT PRIMARY KEY, session_id TEXT REFERENCES sessions(id) ON DELETE RESTRICT, turn_id TEXT REFERENCES turns(id) ON DELETE RESTRICT, parent_id TEXT REFERENCES trace_spans(id) ON DELETE RESTRICT, name TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, attributes_json TEXT NOT NULL);
CREATE TABLE trace_events (id TEXT PRIMARY KEY, span_id TEXT REFERENCES trace_spans(id) ON DELETE RESTRICT, session_id TEXT REFERENCES sessions(id) ON DELETE RESTRICT, turn_id TEXT REFERENCES turns(id) ON DELETE RESTRICT, name TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, attributes_json TEXT NOT NULL);
CREATE TABLE tool_calls (id TEXT PRIMARY KEY, session_id TEXT NOT NULL REFERENCES sessions(id) ON DELETE RESTRICT, turn_id TEXT REFERENCES turns(id) ON DELETE RESTRICT, mcp_server_id TEXT, remote_name TEXT NOT NULL, schema_hash TEXT NOT NULL, started_at TIMESTAMPTZ NOT NULL, ended_at TIMESTAMPTZ, status TEXT NOT NULL, arguments_summary TEXT NOT NULL, result_summary TEXT NOT NULL);
CREATE TABLE eval_cases (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, name TEXT NOT NULL, caller_json TEXT NOT NULL, expect_json TEXT NOT NULL, expected_answer TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL, UNIQUE(agent_id,name));
CREATE TABLE eval_suites (agent_id TEXT PRIMARY KEY REFERENCES agents(id) ON DELETE RESTRICT, runs INTEGER NOT NULL CHECK(runs BETWEEN 1 AND 5), min_pass INTEGER NOT NULL CHECK(min_pass >= 1 AND min_pass <= runs), pass_threshold DOUBLE PRECISION NOT NULL CHECK(pass_threshold BETWEEN 0 AND 1), judge_provider TEXT, judge_model TEXT, updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE eval_scorer_settings (agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, scorer TEXT NOT NULL, threshold DOUBLE PRECISION, judge_provider TEXT, judge_model TEXT, live_enabled BOOLEAN NOT NULL DEFAULT FALSE, sample_rate DOUBLE PRECISION NOT NULL DEFAULT 0 CHECK(sample_rate BETWEEN 0 AND 1), kind TEXT NOT NULL DEFAULT 'builtin' CHECK(kind IN ('builtin','custom')), definition_json TEXT, updated_at TIMESTAMPTZ NOT NULL, PRIMARY KEY(agent_id,scorer));
CREATE TABLE eval_runs (id TEXT PRIMARY KEY, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, agent_version_id TEXT REFERENCES agent_versions(id) ON DELETE RESTRICT, config_hash TEXT NOT NULL, draft BOOLEAN NOT NULL, draft_config_json TEXT, draft_tools_json TEXT, source TEXT NOT NULL CHECK(source IN ('suite')), scope TEXT NOT NULL CHECK(scope IN ('suite','case')), case_id TEXT, providers TEXT NOT NULL CHECK(providers IN ('keep','offline','echo')), runs INTEGER NOT NULL, min_pass INTEGER NOT NULL, status TEXT NOT NULL CHECK(status IN ('pending','running','done')), triggered_by TEXT NOT NULL CHECK(triggered_by IN ('console','api')), passed_cases INTEGER, total_cases INTEGER, created_at TIMESTAMPTZ NOT NULL, started_at TIMESTAMPTZ, ended_at TIMESTAMPTZ, CHECK((draft AND agent_version_id IS NULL) OR (NOT draft AND agent_version_id IS NOT NULL)));
CREATE TABLE eval_results (id TEXT PRIMARY KEY, subject_kind TEXT NOT NULL CHECK(subject_kind IN ('case_run','call')), subject_id TEXT NOT NULL, scorer TEXT NOT NULL, scorer_version INTEGER NOT NULL, version_key TEXT NOT NULL, agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, agent_version_id TEXT, config_hash TEXT NOT NULL, run_id TEXT REFERENCES eval_runs(id) ON DELETE RESTRICT, case_id TEXT, case_hash TEXT, session_id TEXT NOT NULL, score DOUBLE PRECISION NOT NULL, outcome TEXT NOT NULL CHECK(outcome IN ('pass','fail','skipped','error')), reason TEXT NOT NULL, judge_model TEXT, created_at TIMESTAMPTZ NOT NULL, UNIQUE(subject_id,scorer,version_key));
CREATE TABLE eval_jobs (id TEXT PRIMARY KEY, kind TEXT NOT NULL CHECK(kind IN ('run_suite','run_case','score_call')), agent_id TEXT NOT NULL REFERENCES agents(id) ON DELETE RESTRICT, agent_version_id TEXT, run_id TEXT REFERENCES eval_runs(id) ON DELETE RESTRICT, subject TEXT NOT NULL, scorer TEXT, idempotency_key TEXT NOT NULL UNIQUE, status TEXT NOT NULL CHECK(status IN ('pending','running','done','failed','dead')), attempts INTEGER NOT NULL DEFAULT 0, max_attempts INTEGER NOT NULL CHECK(max_attempts >= 1), run_after TIMESTAMPTZ NOT NULL, lease_owner TEXT, lease_expires_at TIMESTAMPTZ, payload TEXT NOT NULL, last_error_category TEXT, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL);
-- +goose StatementBegin
CREATE FUNCTION reject_immutable_update() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'immutable storage row'; END; $$;
-- +goose StatementEnd
CREATE TRIGGER agent_versions_immutable_update BEFORE UPDATE ON agent_versions FOR EACH ROW EXECUTE FUNCTION reject_immutable_update();
CREATE TRIGGER mcp_discoveries_immutable_update BEFORE UPDATE ON mcp_discoveries FOR EACH ROW EXECUTE FUNCTION reject_immutable_update();
CREATE TRIGGER mcp_tools_immutable_update BEFORE UPDATE ON mcp_tools FOR EACH ROW EXECUTE FUNCTION reject_immutable_update();
CREATE TRIGGER agent_versions_immutable_delete BEFORE DELETE ON agent_versions FOR EACH ROW EXECUTE FUNCTION reject_immutable_update();
CREATE TRIGGER mcp_discoveries_immutable_delete BEFORE DELETE ON mcp_discoveries FOR EACH ROW EXECUTE FUNCTION reject_immutable_update();
CREATE TRIGGER mcp_tools_immutable_delete BEFORE DELETE ON mcp_tools FOR EACH ROW EXECUTE FUNCTION reject_immutable_update();
CREATE TRIGGER agent_mcp_tools_immutable_update BEFORE UPDATE ON agent_mcp_tools FOR EACH ROW EXECUTE FUNCTION reject_immutable_update();
CREATE TRIGGER agent_mcp_tools_immutable_delete BEFORE DELETE ON agent_mcp_tools FOR EACH ROW EXECUTE FUNCTION reject_immutable_update();
-- +goose StatementBegin
CREATE FUNCTION reject_current_mcp_delete() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF EXISTS (SELECT 1 FROM agents a JOIN agent_mcp_tools t ON t.agent_version_id=a.current_version_id WHERE t.mcp_server_id=OLD.id) THEN RAISE EXCEPTION 'MCP server referenced by current agent'; END IF; RETURN OLD; END; $$;
-- +goose StatementEnd
CREATE TRIGGER mcp_servers_referenced_delete BEFORE DELETE ON mcp_servers FOR EACH ROW EXECUTE FUNCTION reject_current_mcp_delete();
-- +goose StatementBegin
CREATE FUNCTION check_agent_current_version() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.current_version_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM agent_versions v WHERE v.id=NEW.current_version_id AND v.agent_id=NEW.id) THEN RAISE EXCEPTION 'current version must belong to agent'; END IF; RETURN NEW; END; $$;
-- +goose StatementEnd
CREATE TRIGGER agents_current_version_valid BEFORE INSERT OR UPDATE OF current_version_id ON agents FOR EACH ROW EXECUTE FUNCTION check_agent_current_version();
-- +goose StatementBegin
CREATE FUNCTION check_mcp_latest() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NEW.latest_discovery_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM mcp_discoveries d WHERE d.id=NEW.latest_discovery_id AND d.server_id=NEW.id) THEN RAISE EXCEPTION 'latest discovery must belong to MCP server'; END IF; RETURN NEW; END; $$;
-- +goose StatementEnd
CREATE TRIGGER mcp_servers_latest_valid BEFORE INSERT OR UPDATE OF latest_discovery_id ON mcp_servers FOR EACH ROW EXECUTE FUNCTION check_mcp_latest();
-- +goose StatementBegin
CREATE FUNCTION check_session_provenance() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF NOT EXISTS (SELECT 1 FROM agent_versions v WHERE v.id=NEW.agent_version_id AND v.agent_id=NEW.agent_id AND v.config_hash=NEW.config_hash) THEN RAISE EXCEPTION 'session provenance mismatch'; END IF; RETURN NEW; END; $$;
-- +goose StatementEnd
CREATE TRIGGER sessions_provenance_valid BEFORE INSERT OR UPDATE OF agent_id,agent_version_id,config_hash ON sessions FOR EACH ROW EXECUTE FUNCTION check_session_provenance();
CREATE TRIGGER sessions_provenance_immutable BEFORE UPDATE OF agent_id,agent_version_id,config_hash ON sessions FOR EACH ROW EXECUTE FUNCTION reject_immutable_update();
